func TestAnAnswerWithNoExtensionHasNone(emonT *testing.T) {
	var c *port.Cells = port.NewCells()
	var at int32 = plan.AnOcr(c, 3)
	var w int32 = plan.AnOcrWord(c, at, 10, 20, 30, 40, 900, 0, 0)
	plan.AnOcrCp(c, w, 97)
	plan.AnOcrEnd(c, at)
	port.AssertEq(emonT, ocr.OxFind(c, at), -1, "the words are all there is")
}

func TestTheExtensionFollowsTheWordsAndReadsBack(emonT *testing.T) {
	var c *port.Cells = port.NewCells()
	var at int32 = plan.AnOcr(c, 3)
	var w0 int32 = plan.AnOcrWord(c, at, 10, 20, 30, 40, 900, 0, 0)
	plan.AnOcrCp(c, w0, 72)
	plan.AnOcrCp(c, w0, 105)
	var w1 int32 = plan.AnOcrWord(c, at, 50, 20, 30, 40, 800, 0, 0)
	plan.AnOcrCp(c, w1, 33)
	ocr.OxBegin(c, 1, 2, 3, -85, 90, 1281455214, 17, 187, 1)
	ocr.OxLine(c, 10, 18, 70, 44, 10, 60, 80, 62, 0, 0, 1)
	var x0 int32 = ocr.OxWord(c, 65, 1701734144)
	var s0 int32 = ocr.OxSym(c, x0, 10, 20, 15, 40, 950)
	ocr.OxSymCp(c, s0, 72)
	var a0 int32 = ocr.OxAlt(c, s0, 120)
	ocr.OxAltCp(c, a0, 75)
	var a1 int32 = ocr.OxAlt(c, s0, 80)
	ocr.OxAltCp(c, a1, 78)
	ocr.OxAltCp(c, a1, 77)
	var s1 int32 = ocr.OxSym(c, x0, 25, 20, 15, 40, 900)
	ocr.OxSymCp(c, s1, 105)
	var x1 int32 = ocr.OxWord(c, 0, 0)
	var s2 int32 = ocr.OxSym(c, x1, 50, 20, 30, 40, 800)
	ocr.OxSymCp(c, s2, 33)
	plan.AnOcrEnd(c, at)
	var ext int32 = ocr.OxFind(c, at)
	port.AssertThat(emonT, ext >= 0, "the extension is found after the two words")
	var n1 int32 = plan.AwNext(c, w0)
	port.AssertEq(emonT, ext, plan.AwNext(c, n1), "right after the last word")
	port.AssertEq(emonT, ocr.OxGet(c, ext, 0), ocr.OxVersion(), "version")
	port.AssertEq(emonT, ocr.OxOrient(c, ext), 1, "orient")
	port.AssertEq(emonT, ocr.OxWdir(c, ext), 2, "writing direction")
	port.AssertEq(emonT, ocr.OxTlorder(c, ext), 3, "line order")
	port.AssertEq(emonT, ocr.OxDeskew(c, ext), -85, "deskew in centi-degrees")
	port.AssertEq(emonT, ocr.OxOsd(c, ext), 90, "OSD degrees")
	port.AssertEq(emonT, ocr.OxScript(c, ext), 1281455214, "script, packed")
	port.AssertEq(emonT, ocr.OxSconf(c, ext), 17, "script confidence")
	port.AssertEq(emonT, ocr.OxOconf(c, ext), 187, "orientation confidence")
	port.AssertEq(emonT, ocr.OxNlines(c, ext), 1, "one line")
	var l int32 = ocr.OxLineAt(c, ext, 0)
	port.AssertEq(emonT, l, ext+ocr.OxHeader(), "the line list follows the header")
	port.AssertEq(emonT, port.CellsAt(c, l+6), 80, "baseline end x")
	port.AssertEq(emonT, port.CellsAt(c, l+10), 1, "block type")
	port.AssertEq(emonT, ocr.OxFirstWord(c, ext), l+ocr.OxLineStride(), "the word list follows the lines")
	var wx0 int32 = ocr.OxFirstWord(c, ext)
	port.AssertEq(emonT, ocr.OxWflags(c, wx0), 65, "bold and mono")
	port.AssertEq(emonT, ocr.OxWlang(c, wx0), 1701734144, "eng")
	port.AssertEq(emonT, ocr.OxNsym(c, wx0), 2, "two symbols")
	var sy0 int32 = ocr.OxFirstSym(c, wx0)
	port.AssertEq(emonT, port.CellsAt(c, sy0+4), 950, "symbol confidence")
	port.AssertEq(emonT, port.CellsAt(c, sy0+5), 1, "one code point")
	port.AssertEq(emonT, port.CellsAt(c, sy0+6), 2, "two alternatives")
	port.AssertEq(emonT, port.CellsAt(c, sy0+7), 72, "H")
	var al0 int32 = ocr.OxSymAlts(c, sy0)
	var al1 int32 = ocr.OxAltNext(c, al0)
	port.AssertEq(emonT, port.CellsAt(c, al0), 1, "the first alternative has one code point")
	port.AssertEq(emonT, port.CellsAt(c, al0+1), 120, "its confidence")
	port.AssertEq(emonT, port.CellsAt(c, al0+2), 75, "K")
	port.AssertEq(emonT, port.CellsAt(c, al1), 2, "the second has two")
	port.AssertEq(emonT, port.CellsAt(c, al1+3), 77, "its second code point")
	port.AssertEq(emonT, ocr.OxAltNext(c, al1), ocr.OxSymNext(c, sy0), "the next symbol follows the alternatives")
	var wx1 int32 = ocr.OxWordNext(c, wx0)
	port.AssertEq(emonT, ocr.OxNsym(c, wx1), 1, "the second word has one symbol")
	var s int32 = ocr.OxFirstSym(c, wx1)
	port.AssertEq(emonT, port.CellsAt(c, s+7), 33, "!")
	port.AssertEq(emonT, ocr.OxWordNext(c, wx1), port.CellsLen(c), "and is the last thing in the answer")
}
